class Vault {                     // #store is enforced private by the language
  #store; #policy;
  constructor(store, policy) { this.#store = store; this.#policy = policy; }
  read(who, id) {
    if (!this.#policy.allows(who, id)) throw new AccessDeniedError(id);
    return this.#store.get(id);   // callers never receive #store
  }
}
