function guarded(store, policy) {
  const handler = {
    get(target, prop, receiver) {
      if (!policy.allows(prop)) throw new AccessDeniedError(prop);
      return Reflect.get(target, prop, receiver);   // authorized forwarding
    },
  };
  return Proxy.revocable(store, handler);   // { proxy, revoke }: revoke() cuts the handle
}
